const cfg = $('Settings').first().json;
for (const key of ['accountUid', 'folderUid', 'ledgerTableId', 'teamId', 'channelId']) {
  if (typeof cfg[key] !== 'string' || !cfg[key].trim() || cfg[key].startsWith('YOUR_')) {
    throw new Error(`Set ${key} before running certificate intake. Use one dedicated folder.`);
  }
}
const minimumDays = cfg.minimumValidityDays;
if (!Number.isInteger(minimumDays) || minimumDays < 1 || minimumDays > 365) {
  throw new Error('minimumValidityDays must be a whole number from 1 to 365.');
}
const extensions = String(cfg.allowedExtensions ?? '').split(',').map(v => v.trim().toLowerCase());
if (!extensions.length || extensions.length > 10 || extensions.some(v => !/^[a-z0-9]{1,10}$/.test(v)) || new Set(extensions).size !== extensions.length) {
  throw new Error('allowedExtensions needs unique extensions without dots, for example pdf.');
}
const oneLine = value => String(value ?? '').replace(/[\r\n\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim();
const reviewer = oneLine(cfg.reviewOwner);
if (!reviewer || reviewer.length > 120) throw new Error('Set reviewOwner to a short team or role name.');
const now = new Date();
const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
const events = $('New Folderit file').all();
const seen = new Set();
const output = [];
for (const [index, item] of $input.all().entries()) {
  const file = item.json;
  const event = events[index]?.json;
  if (!event || typeof event.auditUid !== 'string' || !event.auditUid.trim() || event.entityUid !== file.uid || file.type !== 'file') {
    throw new Error('Certificate details do not match a valid new-file audit event.');
  }
  if (file.folderUid !== cfg.folderUid || seen.has(event.auditUid)) continue;
  seen.add(event.auditUid);
  const name = oneLine(file.name);
  const extension = name.includes('.') ? name.slice(name.lastIndexOf('.') + 1).toLowerCase() : '';
  const reasons = [];
  const actions = new Set();
  if (!name) {
    reasons.push('Document name is missing.');
    actions.add('Give the document a meaningful name in Folderit.');
  }
  if (!extensions.includes(extension)) {
    reasons.push(`File extension is not permitted for this intake (${extensions.join(', ')}).`);
    actions.add('Ask the supplier for a permitted file format and check its contents.');
  }
  let dueDate = null;
  let daysRemaining = null;
  let urgent = false;
  if (file.dueDate === null || file.dueDate === undefined || file.dueDate === '') {
    reasons.push('Certificate expiry is not recorded in the standard Folderit Due date.');
    actions.add('Check the certificate and enter its actual expiry in the standard Folderit Due date.');
  } else {
    const parsed = typeof file.dueDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(file.dueDate)
      ? new Date(file.dueDate + 'T00:00:00Z') : null;
    if (!parsed || !Number.isFinite(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== file.dueDate) {
      reasons.push('The standard Folderit Due date is not a valid YYYY-MM-DD calendar date.');
      actions.add('Check the certificate and correct its standard Folderit Due date.');
    } else {
      dueDate = file.dueDate;
      daysRemaining = Math.round((parsed.getTime() - today) / 86400000);
      if (daysRemaining < 0) {
        reasons.push(`Recorded certificate expiry is ${-daysRemaining} UTC calendar day(s) in the past.`);
        actions.add('Request a renewed certificate and have the responsible reviewer check it.');
        urgent = true;
      } else if (daysRemaining === 0) {
        reasons.push('Recorded certificate expiry is today (UTC).');
        actions.add('Contact the supplier for a renewal and review it before relying on the certificate.');
        urgent = true;
      } else if (daysRemaining < minimumDays) {
        reasons.push(`Only ${daysRemaining} UTC calendar day(s) remain; intake requires at least ${minimumDays}.`);
        actions.add('Request a renewal or ask the responsible reviewer to decide how to handle the short validity period.');
      }
    }
  }
  const status = reasons.length ? 'needs_attention' : 'ready_for_review';
  const priority = urgent ? 'urgent' : reasons.length ? 'attention' : 'normal';
  if (!reasons.length) actions.add('Check supplier identity and certificate contents before accepting the document.');
  const nextAction = [...actions].join(' ');
  const lines = [
    `Supplier certificate intake — ${urgent ? 'URGENT DATE CHECK' : reasons.length ? 'NEEDS ATTENTION' : 'READY FOR HUMAN REVIEW'}`,
    `Document: ${name || '(name missing)'}`,
    `Reviewer: ${reviewer}`,
    `Recorded expiry: ${dueDate || '(missing or invalid)'}`,
    `Intake checks: ${reasons.length ? reasons.join(' ') : 'Permitted filename extension and minimum date window are present.'}`,
    `Next action: ${nextAction}`,
    `Document UID: ${file.uid}`,
    `Audit UID: ${event.auditUid}`,
    'This arrival check does not approve the certificate or monitor later corrections.'
  ];
  output.push({json: {
    receiptKey: JSON.stringify(['teams-certificate-intake-v1', cfg.accountUid, event.auditUid, cfg.teamId, cfg.channelId]),
    sourceRef: event.auditUid, status, priority, certificateName: name, dueDate, daysRemaining,
    reasons, nextAction, notificationText: lines.join('\n')
  }, pairedItem: {item: index}});
}
return output;

if (!$execution.id) throw new Error('No execution identity is available; processing was stopped before locking.');
const rows = $input.all().filter(x => x.json.id !== undefined);
if (rows.length !== 1 || rows[0].json.sourceRef !== 'folderit-ledger/v1') throw new Error('Ledger lock is missing, duplicated or has the wrong schema. Run the setup workflow once and inspect the table.');
return rows;

const rows = $input.all().filter(x => x.json.id !== undefined);
if (rows.length !== 1 || rows[0].json.owner !== String($execution.id) || rows[0].json.state !== 'held') throw new Error('Another run owns the processing lock. No destination write was attempted by this run. Retain this failed input and retry after the owner completes.');
return rows;

const item = $('Process one item').item;
const rows = $input.all().filter(x => x.json.id !== undefined);
if (rows.length > 1) throw new Error('Duplicate ledger keys need reconciliation. No destination write was attempted.');
if (rows.length === 1) {
  const receipt = rows[0].json;
  if (receipt.key !== item.json.receiptKey || (item.json.payloadHash && receipt.payloadHash !== item.json.payloadHash)) throw new Error('The receipt does not match this work item. Inspect before continuing.');
  if (receipt.state !== 'done' || !receipt.targetUid) throw new Error('A prior attempt is unresolved. Inspect the receipt, its owner execution and the destination before clearing the processing lock. Do not repeat the write.');
  return [{json: {...item.json, route: 'done', targetUid: receipt.targetUid, receiptRowId: receipt.id}, binary: item.binary, pairedItem: {item: 0}}];
}
return [{json: {...item.json, route: 'new'}, binary: item.binary, pairedItem: {item: 0}}];

const rows = $input.all().filter(x => x.json.id !== undefined);
const source = $('Process one item').item;
if (rows.length !== 1 || rows[0].json.state !== 'pending' || rows[0].json.owner !== String($execution.id) || rows[0].json.key !== source.json.receiptKey) throw new Error('Pending receipt was not saved as expected. No destination write was attempted.');
return [{json: {...source.json, receiptRowId: rows[0].json.id}, binary: source.binary, pairedItem: {item: 0}}];

const expected=$('Restore work item').item.json; const result=$input.first().json;
if(!result.id || typeof result.id!=='string')throw new Error('No Teams message ID was returned. Inspect the channel before repeating this notification.');
return [{json:{receiptRowId:expected.receiptRowId,targetUid:result.id},pairedItem:{item:0}}];

const rows = $input.all().filter(x => x.json.id !== undefined);
const expected = $('Verify destination result').item.json;
if (rows.length !== 1 || rows[0].json.state !== 'done' || rows[0].json.targetUid !== expected.targetUid || rows[0].json.owner !== String($execution.id)) throw new Error('The destination action succeeded but its receipt could not be confirmed. Inspect before retrying.');
return [{json: {status: 'completed', targetUid: rows[0].json.targetUid, receiptKey: rows[0].json.key}, pairedItem: {item: 0}}];

const rows = $input.all().filter(x => x.json.id !== undefined);
if (rows.length !== 1 || rows[0].json.state !== 'free' || rows[0].json.owner !== '' || rows[0].json.key !== '__mutex__') throw new Error('Could not confirm processing lock release. Inspect the table and owner execution.');
return [{json: {lockReleased: true}}];
